const client={auth:{getSession:async()=>({data:{session:null}})},from(table){const q={select(){return q},eq(){return q},is(){return q},order(){return q},limit(){return q},single(){return q},then(resolve){return Promise.resolve({data:table==='profiles'?{username:'marie'}:[],count:0}).then(resolve)}};return q},async rpc(name,{p_action}={}){if(name==='nm_social')return{data:['list','recipients'].includes(p_action)?[{status:'accepted',account_tier:'pro',profile_type:'PO',display_name:'Camille',handle:'camille.nails',user_id:'pro',workspaces:[{entity_id:'workspace',pro_handle:'atelier.camille',workspace_name:'Atelier Camille'}]},{status:'accepted',account_tier:'plus',profile_type:'Plus',display_name:'Émilie',handle:'emilie.moods',user_id:'plus',workspaces:[]}]:{messages:[]}};if(name==='search_nailmoods')return{data:[{entity_type:'workspace',entity_id:'workspace',display_name:'Atelier Camille',handle:'atelier.camille'}]};return{data:'share-id'};}};
